import {RBMachine,isRed,snapshotPaths} from './redblack-lab-engine.js';
export function treeFromSequence(keys){return new RBMachine(keys).snapshot()}
export function treeSignature(n){return n.nil?'_':`${n.key}${n.color}(${treeSignature(n.left)},${treeSignature(n.right)})`}
export function countNodes(n){return n.nil?0:1+countNodes(n.left)+countNodes(n.right)}
export function validateRB(n,min=-Infinity,max=Infinity){if(n.nil){if(n.color!=='B')throw Error('NIL must be black');return 1}if(!(n.key>min&&n.key<max))throw Error('BST ordering');if(n.color==='R'&&(isRed(n.left)||isRed(n.right)))throw Error('red/red');const a=validateRB(n.left,min,n.key),b=validateRB(n.right,n.key,max);if(a!==b)throw Error('black height');return a+(n.color==='B'?1:0)}
export function cascadeFamily(level){if(!Number.isInteger(level)||level<0||level>5)throw Error('层数为 0–5');let serial=0,key=0;const nil=()=>({nil:true,id:'f'+(++serial),color:'B'}),node=(color,left=nil(),right=nil())=>({nil:false,id:'f'+(++serial),key:0,color,left,right});function black(h){return h===0?nil():node('B',black(h-1),black(h-1))}function chain(h){return h===0?node('B'):node('B',node('R',chain(h-1),black(h)),node('R',black(h),black(h)))}const root=chain(level);function label(n){if(!n.nil){label(n.left);n.key=++key*10;label(n.right)}}label(root);return root}
class InsertionMachine{
 constructor(root,mode){this.mode=mode;this.serial=0;const clone=(n,p=null)=>{const out={id:n.id,key:n.key,color:n.color,nil:n.nil,parent:p};if(!n.nil){out.left=clone(n.left,out);out.right=clone(n.right,out)}return out};this.root=clone(root);this.frames=[];this.stats={rotations:0,splits:0,recolors:0,visits:0,upward:0};this.inserted=false;this.operation=0;this.visited=[];this.record('start','相同初始树','两边从完全相同的键、结构和颜色开始。')}
 nil(p){return{nil:true,color:'B',id:'new-e'+(++this.serial),parent:p}}
 make(key,p){const n={id:'new-n'+(++this.serial),key,color:'R',nil:false,parent:p};n.left=this.nil(n);n.right=this.nil(n);return n}
 snap(n=this.root){return n.nil?{id:n.id,nil:true,color:'B'}:{id:n.id,key:n.key,color:n.color,nil:false,left:this.snap(n.left),right:this.snap(n.right)}}
 record(type,title,text,focus=[]){const root=this.snap();this.frames.push({root,type,title,text,focus:[...focus],stats:{...this.stats},inserted:this.inserted,operation:this.operation,visited:[...this.visited],paths:snapshotPaths(root)})}
 color(n,c){if(n.color!==c){this.stats.recolors++;n.color=c}}
 rotate(p,left){const s=left?p.right:p.left,g=p.parent;if(s.nil)throw Error('rotate NIL');if(left){p.right=s.left;p.right.parent=p;s.left=p}else{p.left=s.right;p.left.parent=p;s.right=p}p.parent=s;s.parent=g;if(!g)this.root=s;else g[g.left===p?'left':'right']=s;this.stats.rotations++;return s}
 normalize(){if(this.root.color!=='B'){this.color(this.root,'B');this.record('root','根恢复为黑','所有根到 NIL 路径一起增加一个黑色；计入实际颜色变化。',[this.root.id])}}
 repair(x){let p=x.parent,g=p.parent,left=p===g.left;const roles=[x.id,p.id,g.id];if(x===(left?p.right:p.left)){this.rotate(p,left);this.record('rotate','折线先拉直','先让当前节点上升一次，颜色保持。',roles);x=p;p=x.parent;g=p.parent}this.color(p,'B');this.color(g,'R');this.rotate(g,!left);this.record('rotate','换色并旋转局部祖父',this.mode==='top'?'父节点上升为黑，祖父下降为红；从新的局部根继续下降，不执行向上回溯。':'父节点上升为黑，祖父下降为红；局部修复完成，结束向上处理。',roles);return p}
 visit(x){this.stats.visits++;this.visited.push(x.id);this.record('visit',`下降到 ${x.key}`,this.mode==='top'?'先检查当前节点的两个孩子是否都红，再选择下一条边。':'只比较键，下降阶段不改颜色、不旋转。',[x.id])}
 bottom(key){let p=null,x=this.root;while(!x.nil){this.visit(x);if(x.key===key){this.record('complete','重复键：集合不变','Bottom-up 在搜索阶段就返回，因此结构和颜色也不变。');return}p=x;x=key<x.key?x.left:x.right}x=this.make(key,p);if(!p)this.root=x;else p[key<p.key?'left':'right']=x;this.inserted=true;this.record('insert',`挂入红叶 ${key}`,'先完成普通 BST 插入，再从新节点向上修复。',[x.id,p?.id].filter(Boolean));while(isRed(x.parent)){const p=x.parent,g=p.parent,u=p===g.left?g.right:g.left;if(isRed(u)){this.stats.splits++;this.color(p,'B');this.color(u,'B');this.color(g,'R');this.stats.upward++;this.record('split',`向上分裂：祖父 ${g.key}`,'红父与红叔变黑，祖父变红；把冲突交给祖父继续检查。',[p.id,u.id,g.id]);x=g}else{this.repair(x);break}}this.normalize();this.record('complete','Bottom-up 插入完成','完整红黑性质恢复；没有冲突就不会预先拆开祖先的 4-node。')}
 top(key){let q=this.root,p=null;while(!q.nil){this.visit(q);if(isRed(q.left)&&isRed(q.right)){this.stats.splits++;this.color(q,'R');this.color(q.left,'B');this.color(q.right,'B');this.record('split',`下降中分裂：节点 ${q.key}`,'还没有挂入新键，就先拆当前 4-node：当前节点红，两个孩子黑。',[q.id,q.left.id,q.right.id]);if(isRed(q.parent))q=this.repair(q);this.normalize()}if(q.key===key){this.record('complete','重复键：集合不变，但可能已经调整','本 Top-down 约定先分裂、后检查相等；途中已经发生的变色/旋转保留。');return}p=q;q=key<q.key?q.left:q.right}const x=this.make(key,p);if(!p)this.root=x;else p[key<p.key?'left':'right']=x;this.inserted=true;this.record('insert',`挂入红叶 ${key}`,'下降路径已经预处理；若此时出现红红冲突，只需局部旋转收尾。',[x.id,p?.id].filter(Boolean));if(isRed(x.parent))this.repair(x);this.normalize();this.record('complete','Top-down 插入完成','沿途遇到的 4-node 已经分裂。没有最后一次从叶子返回根的修复循环。')}
 run(keys){for(const k of keys){this.operation++;this.inserted=false;this.record('begin',`准备插入 ${k}`,'操作边界；后续统计为本次对比序列累计值。');this[this.mode==='top'?'top':'bottom'](k)}return this.frames}
}
export function compareInsert(root,keys){validateRB(root);if(root.color!=='B')throw Error('根必须黑');if(!keys.length||keys.length>24||keys.some(k=>!Number.isSafeInteger(k)||Math.abs(k)>9999))throw Error('请输入 1–24 个 −9999…9999 的整数');const bottom=new InsertionMachine(root,'bottom').run(keys),top=new InsertionMachine(root,'top').run(keys);return{initial:root,keys,bottom,top,bottomFinal:bottom.at(-1),topFinal:top.at(-1),sameFinal:treeSignature(bottom.at(-1).root)===treeSignature(top.at(-1).root)}}
export const comparePresets=[
 {id:'rotations',name:'主例 · Bottom-up 零修复，Top-down 两次旋转',initial:'130 120 20 10 170 180 60 40 30 80 160 150 140 50 70 100 90',insert:'110',why:'先按同一序列用 Bottom-up 建好初始树，再复制给两种算法。插入 110 的父亲为黑；Top-down 却会提前分裂 80，触发折线双旋，最终树形不同。'},
 {id:'extreme',name:'极端主例 · 路上多层满结点，叶父却黑',kind:'family',level:3,insert:'0',why:'Bottom-up 新红叶的父亲黑，完全不用修；Top-down 仍须把下降途中每个 4-node 预先分裂。层数可调，差异可以继续放大。'},
 {id:'small',name:'小型教学例 · 7 个节点就能看出颜色差异',kind:'family',level:1,insert:'0',why:'根有两个红孩子，但最小叶子为黑。插入 0 后 Bottom-up 不变色，Top-down 先把根的两个孩子变黑。'},
 {id:'upward',name:'对照例 · 同样分裂，时间顺序相反',initial:'40 20 60 10 30 50 70',insert:'5',why:'两边都要处理满结点，但 Bottom-up 等新红叶引发冲突后才向上处理，Top-down 先在下降中处理。'},
 {id:'duplicate',name:'边界反例 · 键早已存在也可能调整',kind:'family',level:2,insert:'10',why:'Bottom-up 查到重复键直接结束。Top-down 若按本页“先分裂再判等”的规则实现，即使不新增键，也可能已经改变颜色或结构。'}
];
